{
  "name": "双束聚焦离子束扫描电子显微镜",
  "name_en": "DualBeam FIB-SEM microscope",
  "manufacturer": "Thermo Fisher Scientific",
  "description": "这是一类将扫描电子显微镜与聚焦离子束集成在同一平台上的双束显微镜，可用于样品表面成像、离子束刻蚀与铣削、气体辅助沉积、样品台精密定位以及自动对准。它常用于截面制备、薄片制备、沟槽铣削、序列切片成像和体成像等实验流程。",
  "description_en": "This is a dual-beam microscope that combines a scanning electron microscope with a focused ion beam on one platform. It is used for surface imaging, ion-beam milling and patterning, gas-assisted deposition, precise stage positioning, and automated alignment. Typical lab uses include cross-section preparation, lamella preparation, trench milling, serial sectioning, and volume imaging workflows.",
  "tag_hints": [
    "FIB-SEM",
    "ion beam milling",
    "SEM imaging",
    "lamella preparation",
    "serial sectioning",
    "gas injection system",
    "volume imaging"
  ],
  "actions": [
    {
      "action_name": "auto-define_output_dir",
      "description": "定义图像采集与铣削流程的输出目录",
      "description_en": "Define the output directory for imaging and milling workflows"
    },
    {
      "action_name": "auto-stop",
      "description": "停止当前自动运行流程",
      "description_en": "Stop the current automated workflow"
    },
    {
      "action_name": "auto-define_SAVparams_file",
      "description": "定义切片体成像流程使用的参数文件",
      "description_en": "Define the parameter file used for the slice-and-view workflow"
    },
    {
      "action_name": "auto-stop_patterning",
      "description": "停止正在进行的图案铣削",
      "description_en": "Stop the ongoing patterning or milling operation"
    },
    {
      "action_name": "auto-is_idle",
      "description": "获取设备是否处于空闲状态",
      "description_en": "Get whether the microscope is idle"
    },
    {
      "action_name": "auto-get_current",
      "description": "获取当前离子束电流",
      "description_en": "Get the current ion beam current"
    },
    {
      "action_name": "auto-insert_GIS",
      "description": "插入气体注入系统针头",
      "description_en": "Insert the gas injection system needle"
    },
    {
      "action_name": "auto-retract_GIS",
      "description": "缩回气体注入系统针头",
      "description_en": "Retract the gas injection system needle"
    },
    {
      "action_name": "auto-open_GIS",
      "description": "打开气体注入系统指定时长",
      "description_en": "Open the gas injection system for a specified duration"
    },
    {
      "action_name": "auto-ion_on",
      "description": "开启离子束",
      "description_en": "Turn on the ion beam"
    },
    {
      "action_name": "auto-electron_on",
      "description": "开启电子束",
      "description_en": "Turn on the electron beam"
    },
    {
      "action_name": "auto-setIonHFW",
      "description": "设置离子束视场宽度",
      "description_en": "Set the ion beam horizontal field width"
    },
    {
      "action_name": "auto-link_stage",
      "description": "链接样品台坐标系统",
      "description_en": "Link the stage coordinate system"
    },
    {
      "action_name": "auto-unlink_stage",
      "description": "解除样品台坐标系统链接",
      "description_en": "Unlink the stage coordinate system"
    },
    {
      "action_name": "auto-take_image_IB",
      "description": "采集离子束图像",
      "description_en": "Acquire an ion beam image"
    },
    {
      "action_name": "auto-take_image_EB",
      "description": "采集电子束图像",
      "description_en": "Acquire an electron beam image"
    },
    {
      "action_name": "auto-take_image_EB_SAV",
      "description": "按切片体成像参数采集电子束图像",
      "description_en": "Acquire electron beam images using slice-and-view parameters"
    },
    {
      "action_name": "auto-getStagePosition",
      "description": "获取当前样品台位置",
      "description_en": "Get the current stage position"
    },
    {
      "action_name": "auto-moveStageAbsolute",
      "description": "将样品台移动到指定绝对位置",
      "description_en": "Move the stage to a specified absolute position"
    },
    {
      "action_name": "auto-moveStageRelative",
      "description": "按给定偏移量相对移动样品台",
      "description_en": "Move the stage relatively by a specified offset"
    },
    {
      "action_name": "auto-print_stage_rot",
      "description": "输出样品台旋转角信息",
      "description_en": "Report the stage rotation angle information"
    },
    {
      "action_name": "auto-align",
      "description": "根据参考图像对准样品台与束斑",
      "description_en": "Align the stage and beam using a reference image"
    },
    {
      "action_name": "auto-align_current",
      "description": "改变束流后重新对准到参考位置",
      "description_en": "Realign to the reference position after changing beam current"
    },
    {
      "action_name": "auto-auto_focus",
      "description": "执行自动对焦",
      "description_en": "Run autofocus"
    },
    {
      "action_name": "auto-create_pattern",
      "description": "创建矩形铣削图案",
      "description_en": "Create a rectangular milling pattern"
    },
    {
      "action_name": "auto-pattern_parser",
      "description": "从图案文件导入铣削图案",
      "description_en": "Import a milling pattern from a pattern file"
    },
    {
      "action_name": "auto-pattern_directory_parser",
      "description": "从目录导入全部铣削图案",
      "description_en": "Import all milling patterns from a directory"
    },
    {
      "action_name": "auto-save_pattern",
      "description": "保存铣削图案到文件",
      "description_en": "Save a milling pattern to a file"
    },
    {
      "action_name": "auto-auto_cb",
      "description": "执行自动对比度与亮度调整",
      "description_en": "Run automatic contrast and brightness adjustment"
    },
    {
      "action_name": "auto-create_trench_patterns",
      "description": "创建沟槽铣削图案",
      "description_en": "Create trench milling patterns"
    },
    {
      "action_name": "auto-run_trench_milling",
      "description": "运行沟槽铣削流程",
      "description_en": "Run a trench milling workflow"
    },
    {
      "action_name": "auto-run_milling",
      "description": "运行指定铣削图案",
      "description_en": "Run the specified milling patterns"
    },
    {
      "action_name": "auto-create_custom_protocol",
      "description": "创建自定义铣削协议",
      "description_en": "Create a custom milling protocol"
    },
    {
      "action_name": "auto-create_custom_patterns",
      "description": "创建自定义图案序列",
      "description_en": "Create a custom pattern sequence"
    },
    {
      "action_name": "auto-write_patterns",
      "description": "写出图案与对应对准图像记录",
      "description_en": "Write out pattern data together with the associated alignment image record"
    },
    {
      "action_name": "auto-run_custom_milling",
      "description": "按自定义步骤运行铣削",
      "description_en": "Run milling according to custom steps"
    },
    {
      "action_name": "auto-run_milling_custom",
      "description": "按自定义序列执行铣削流程",
      "description_en": "Execute a milling workflow using a custom sequence"
    },
    {
      "action_name": "auto-custom_file_parser",
      "description": "解析自定义铣削步骤文件",
      "description_en": "Parse a custom milling step file"
    },
    {
      "action_name": "auto-run_SAV",
      "description": "运行切片-观察体成像流程",
      "description_en": "Run a slice-and-view volume imaging workflow"
    },
    {
      "action_name": "auto-create_SAV_patterns",
      "description": "创建切片-观察体成像用铣削图案",
      "description_en": "Create milling patterns for slice-and-view imaging"
    },
    {
      "action_name": "auto-makePatterns_SAV",
      "description": "生成切片-观察体成像图案",
      "description_en": "Generate slice-and-view patterns"
    },
    {
      "action_name": "auto-run_milling_protocol",
      "description": "按协议运行铣削流程",
      "description_en": "Run a milling workflow according to a protocol"
    }
  ]
}

